insert into districts values ('ariyalur', 'tamil-nadu', 610, 'Ariyalur', 'Ariyalur', 'Ariyalur', 'Its rocks are full of fossils of sea creatures that lived here millions of years ago, and it is home to the Gangaikonda Cholapuram temple built by Rajendra Chola I.', true, array['cuddalore','perambalur','tiruchirappalli','thanjavur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('chengalpattu', 'tamil-nadu', 730, 'Chengalpattu', 'Chengalpattu', 'Chengalpattu', 'Mamallapuram''s Shore Temple and stone carvings, a UNESCO World Heritage Site, are in this district. So is Vedanthangal, one of India''s oldest bird sanctuaries.', true, array['chennai','thiruvallur','tiruvannamalai','villupuram','kanchipuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('chennai', 'tamil-nadu', 568, 'Chennai', 'Chennai', 'Chennai', 'Chennai is the state capital, and Marina Beach is one of the longest city beaches in the world.', true, array['chengalpattu','thiruvallur','kanchipuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('coimbatore', 'tamil-nadu', 569, 'Coimbatore', 'Coimbatore', 'Coimbatore', 'Coimbatore is nicknamed the ''Manchester of South India'' because of its many textile mills.', true, array['erode','the-nilgiris','tiruppur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('cuddalore', 'tamil-nadu', 570, 'Cuddalore', 'Cuddalore', 'Cuddalore', 'Pichavaram, one of the world''s largest mangrove forests, lets you row a boat through tunnels of trees.', true, array['ariyalur','kallakurichi','perambalur','villupuram','mayiladuthurai','thanjavur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('dharmapuri', 'tamil-nadu', 571, 'Dharmapuri', 'Dharmapuri', 'Dharmapuri', 'At Hogenakkal Falls the Kaveri river crashes over rocks, and people cross the water in round coracle boats.', true, array['kallakurichi','salem','tiruvannamalai','krishnagiri']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('dindigul', 'tamil-nadu', 572, 'Dindigul', 'Dindigul', 'Dindigul', 'Dindigul is famous for strong locks and tasty biryani. The hill station Kodaikanal is also in this district.', true, array['karur','madurai','theni','tiruchirappalli','tiruppur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('erode', 'tamil-nadu', 573, 'Erode', 'Erode', 'Erode', 'Erode is called ''Turmeric City'' — it has some of the biggest turmeric markets in India.', true, array['coimbatore','karur','the-nilgiris','namakkal','salem','tiruppur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('kallakurichi', 'tamil-nadu', 729, 'Kallakurichi', 'Kallakurichi', 'Kallakurichi', 'One of Tamil Nadu''s newer districts (2019), it is home to the green Kalvarayan Hills.', true, array['cuddalore','dharmapuri','perambalur','salem','tiruvannamalai','villupuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('kanchipuram', 'tamil-nadu', 574, 'Kancheepuram', 'Kanchipuram', 'Kancheepuram', 'Known as the ''City of a Thousand Temples'', it is also famous for beautiful silk sarees.', true, array['chengalpattu','chennai','ranipet','thiruvallur','tiruvannamalai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('kanniyakumari', 'tamil-nadu', 575, 'Kanniyakumari', 'Kanniyakumari', 'Nagercoil', 'At the southern tip of mainland India, you can watch the sun rise and set over the sea. The tall Thiruvalluvar statue stands here.', true, array['tirunelveli']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('karur', 'tamil-nadu', 576, 'Karur', 'Karur', 'Karur', 'Karur weaves bedsheets, curtains and towels that are sent all over the world.', true, array['dindigul','erode','namakkal','tiruchirappalli','tiruppur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('krishnagiri', 'tamil-nadu', 577, 'Krishnagiri', 'Krishnagiri', 'Krishnagiri', 'Krishnagiri grows so many mangoes that it is one of the biggest mango-producing districts in the state.', true, array['dharmapuri','tirupathur','tiruvannamalai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('madurai', 'tamil-nadu', 578, 'Madurai', 'Madurai', 'Madurai', 'Madurai is one of the oldest cities in India and home to the colourful Meenakshi Amman Temple.', true, array['dindigul','sivaganga','theni','tiruchirappalli','virudhunagar']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('mayiladuthurai', 'tamil-nadu', 735, 'Mayiladuthurai', 'Mayiladuthurai', 'Mayiladuthurai', 'Tamil Nadu''s newest district (formed from Nagapattinam). Its name means ''town of peacocks'', and the old Chola port of Poompuhar is here.', true, array['cuddalore','thiruvarur','thanjavur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('nagapattinam', 'tamil-nadu', 579, 'Nagapattinam', 'Nagapattinam', 'Nagapattinam', 'Point Calimere (Kodiyakkarai) sanctuary here welcomes thousands of pink flamingos every winter.', true, array['thiruvarur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('namakkal', 'tamil-nadu', 580, 'Namakkal', 'Namakkal', 'Namakkal', 'Namakkal is known as ''Egg City'' because its poultry farms produce millions of eggs every day.', true, array['erode','karur','salem','tiruchirappalli']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('perambalur', 'tamil-nadu', 581, 'Perambalur', 'Perambalur', 'Perambalur', 'The Ranjankudi Fort here was built hundreds of years ago and has three layers of walls.', true, array['ariyalur','cuddalore','kallakurichi','salem','tiruchirappalli']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('pudukkottai', 'tamil-nadu', 582, 'Pudukkottai', 'Pudukkottai', 'Pudukkottai', 'The Sittanavasal rock-cut cave has ancient paintings of lotus ponds, fish and elephants.', true, array['ramanathapuram','sivaganga','tiruchirappalli','thanjavur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('ramanathapuram', 'tamil-nadu', 583, 'Ramanathapuram', 'Ramanathapuram', 'Ramanathapuram', 'Rameswaram island and the Pamban bridge over the sea are in this district.', true, array['sivaganga','tuticorin','virudhunagar','pudukkottai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('ranipet', 'tamil-nadu', 731, 'Ranipet', 'Ranipet', 'Ranipet', 'Formed in 2019 from Vellore, Ranipet is known for leather and chemical industries.', true, array['thiruvallur','tiruvannamalai','vellore','kanchipuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('salem', 'tamil-nadu', 584, 'Salem', 'Salem', 'Salem', 'Salem has a big steel plant and the cool hill station Yercaud, sometimes called the ''Jewel of the South''.', true, array['dharmapuri','erode','kallakurichi','namakkal','perambalur','tiruchirappalli']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('sivaganga', 'tamil-nadu', 585, 'Sivaganga', 'Sivaganga', 'Sivaganga', 'Keeladi in Sivaganga revealed an ancient Sangam-era town. The Chettinad mansions of Karaikudi are here too.', true, array['madurai','ramanathapuram','tiruchirappalli','virudhunagar','pudukkottai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tenkasi', 'tamil-nadu', 733, 'Tenkasi', 'Tenkasi', 'Tenkasi', 'The Courtallam waterfalls here are so refreshing that the town is called the ''Spa of South India''.', true, array['tirunelveli','tuticorin','virudhunagar']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('thanjavur', 'tamil-nadu', 586, 'Thanjavur', 'Thanjavur', 'Thanjavur', 'The 1,000-year-old Brihadeeswarar (Big) Temple is here. Thanjavur is called the ''Rice Bowl of Tamil Nadu''.', true, array['ariyalur','cuddalore','thiruvarur','tiruchirappalli','mayiladuthurai','pudukkottai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('the-nilgiris', 'tamil-nadu', 587, 'The Nilgiris', 'The Nilgiris', 'Udhagamandalam (Ooty)', '''Nilgiri'' means blue mountains. The Nilgiri Mountain Railway toy train is a UNESCO World Heritage Site.', true, array['coimbatore','erode']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('theni', 'tamil-nadu', 588, 'Theni', 'Theni', 'Theni', 'In the Western Ghats, Theni''s Cumbum valley grows grapes, and the Vaigai dam is here.', true, array['dindigul','madurai','virudhunagar']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('thiruvallur', 'tamil-nadu', 589, 'Thiruvallur', 'Thiruvallur', 'Thiruvallur', 'Pulicat Lake, one of India''s largest brackish-water lagoons, is in Thiruvallur.', true, array['chengalpattu','chennai','ranipet','vellore','kanchipuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('thiruvarur', 'tamil-nadu', 590, 'Thiruvarur', 'Thiruvarur', 'Thiruvarur', 'The Thyagaraja Temple''s chariot is one of the largest temple chariots in India.', true, array['nagapattinam','mayiladuthurai','thanjavur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tuticorin', 'tamil-nadu', 594, 'Thoothukudi', 'Tuticorin', 'Thoothukudi', 'Thoothukudi is called the ''Pearl City'' because pearls were collected from its sea for centuries.', true, array['ramanathapuram','tenkasi','tirunelveli','virudhunagar']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tiruchirappalli', 'tamil-nadu', 591, 'Tiruchirappalli', 'Tiruchirappalli', 'Tiruchirappalli', 'The Rockfort temple sits on top of a giant rock, and Srirangam has one of the largest temple complexes in the world.', true, array['ariyalur','dindigul','karur','madurai','namakkal','perambalur','salem','sivaganga','thanjavur','pudukkottai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tirunelveli', 'tamil-nadu', 592, 'Tirunelveli', 'Tirunelveli', 'Tirunelveli', 'Tirunelveli is famous for its sweet halwa and the Thamirabarani river.', true, array['kanniyakumari','tenkasi','tuticorin']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tirupathur', 'tamil-nadu', 732, 'Tirupathur', 'Tirupathur', 'Tirupathur', 'Formed in 2019 from Vellore, it is home to the Yelagiri hills.', true, array['tiruvannamalai','vellore','krishnagiri']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tiruppur', 'tamil-nadu', 634, 'Tiruppur', 'Tiruppur', 'Tiruppur', 'Tiruppur is the ''Knitwear Capital of India'' — many T-shirts sold around the world are made here.', true, array['coimbatore','dindigul','erode','karur']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('tiruvannamalai', 'tamil-nadu', 593, 'Tiruvannamalai', 'Tiruvannamalai', 'Tiruvannamalai', 'During Karthigai Deepam, a giant lamp is lit on top of the Annamalai hill.', true, array['chengalpattu','dharmapuri','kallakurichi','ranipet','tirupathur','vellore','villupuram','krishnagiri','kanchipuram']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('vellore', 'tamil-nadu', 595, 'Vellore', 'Vellore', 'Vellore', 'Vellore Fort is surrounded by a water-filled moat.', true, array['ranipet','tirupathur','thiruvallur','tiruvannamalai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('villupuram', 'tamil-nadu', 596, 'Viluppuram', 'Villupuram', 'Viluppuram', 'Gingee Fort, built across three hills, was once called the ''Troy of the East''.', true, array['chengalpattu','cuddalore','kallakurichi','tiruvannamalai']::text[], '/data/districts/tamil-nadu.topo.json');
insert into districts values ('virudhunagar', 'tamil-nadu', 597, 'Virudhunagar', 'Virudhunagar', 'Virudhunagar', 'Sivakasi in this district makes fireworks, matches and printed calendars. The Srivilliputhur temple tower appears on the state emblem.', true, array['madurai','ramanathapuram','sivaganga','theni','tenkasi','tuticorin']::text[], '/data/districts/tamil-nadu.topo.json');
